INSERT INTO `species` VALUES (1,'cultrata','Anoura cultrata','Anoura','Phyllostomidae','Bat','Nectarivore','6;5','5.666666667',NULL,NULL,NULL,'I would keep this one as a nectarivorous bat, although I agree, many nectarivores feed also on fruit and insects, also Glossophaga... nevertheless, I would say they are less \"omnivore\" than Phyllostomus for example; however, there might be room for interpretation!!! omnivore (fruit, pollen, nectar, occasionally insects)'),(2,'geoffroyi','Anoura geoffroyi','Anoura','Phyllostomidae','Bat','Nectarivore','6;5;5','5.5',NULL,NULL,NULL,'None'),(3,'fraterculus','Artibeus fraterculus','Artibeus','Phyllostomidae','Bat',NULL,'None','nan',NULL,NULL,NULL,'None'),(4,'hirsutus','Artibeus hirsutus','Artibeus','Phyllostomidae','Bat','Frugivore','6;6;4;4','5.4',NULL,NULL,NULL,'None'),(5,'intermedius','Artibeus intermedius','Artibeus','Phyllostomidae','Bat','Frugivore','1;1;3','1.333333333',NULL,NULL,NULL,'subspecies of A. lituratus'),(6,'jamaicensis','Artibeus jamaicensis','Artibeus','Phyllostomidae','Bat','Frugivore','6;3;3;4;1;1;4;5;4','3.511111111',NULL,NULL,NULL,'None'),(7,'lituratus','Artibeus lituratus','Artibeus','Phyllostomidae','Bat','Frugivore','1;1;3','1.333333333',NULL,NULL,NULL,'None'),(8,'planirostris','Artibeus planirostris','Artibeus','Phyllostomidae','Bat','Frugivore','1','1.0',NULL,NULL,NULL,'None'),(9,'toltecus','Artibeus toltecus','Artibeus','Phyllostomidae','Bat','Frugivore','6;5;4;1;1','4.333333333',NULL,NULL,NULL,'None'),(10,'plicata','Balantiopteryx plicata','Balantiopteryx',NULL,'Bat','Insectivore','6;6;6;4;3;4','5.333333333',NULL,NULL,NULL,'None'),(11,'barbastellus','Barbastella barbastellus','Barbastella',NULL,'Bat','Insectivore','3;4;2 : 6;6;5','4.055555556',NULL,NULL,NULL,'formula for differential summer & winter roosting: (summer roosting formula *2 + winter roosting formula) / 3'),(12,'dubiaquercus','Bauerus dubiaquercus','Bauerus','Vespertilionidae','Bat','Insectivore','3','3.0',NULL,NULL,NULL,'None'),(13,'brevicauda','Carollia brevicauda','Carollia','Phyllostomidae','Bat','Frugivore','3;6;5;6;5;4;4','4.75',NULL,NULL,NULL,'Panama & South America'),(14,'castanea','Carollia castanea','Carollia','Phyllostomidae','Bat','Frugivore','6;5;3;6;3','4.933333333',NULL,NULL,NULL,'None'),(15,'perspicillata','Carollia perspicillata','Carollia','Phyllostomidae','Bat','Frugivore','6;5;6;5;3;3;4;4','4.916666667',NULL,NULL,NULL,'None'),(16,'sowelli','Carollia sowelli','Carollia','Phyllostomidae','Bat','Frugivore','6;3;5;4;1','4.666666667',NULL,NULL,NULL,'None'),(17,'subrufa','Carollia subrufa','Carollia','Phyllostomidae','Bat','Frugivore','6;3;4','4.666666667',NULL,NULL,NULL,'I would say Carollias are predominantly frugivores, however they for sure eat also other stuff, as most bats will do... For example if an Aj eats a fig with fig wasps inside, is it insectivore? omnivore (fruit, nectar, occasionally insects)'),(18,'villosum','Chiroderma villosum','Chiroderma','Phyllostomidae','Bat','Frugivore','3;4','3.333333333',NULL,NULL,NULL,'None'),(19,'mexicana','Choeronycteris mexicana','Choeronycteris',NULL,'Bat','Nectarivore','6;6;4;3','5.3',NULL,NULL,NULL,'None'),(20,'auritus','Chrotopterus auritus','Chrotopterus','Phyllostomidae','Bat','Animalivore','6;4;4;3;2','4.4',NULL,NULL,NULL,'to separate between animalivore and insectivore is the next challenge!'),(21,'mexicanus','Corynorhinus mexicanus','Corynorhinus',NULL,'Bat','Insectivore','6;6;4;3','5.3',NULL,NULL,NULL,'None'),(22,'azteca','Dermanura azteca','Dermanura','Phyllostomidae','Bat','Frugivore','1;5;6;4;5?','3.733333333',NULL,NULL,NULL,'None'),(23,'cinerea','Dermanura cinerea','Dermanura','Phyllostomidae','Bat','Frugivore','1','1.0',NULL,NULL,NULL,'only eastern South America?'),(24,'phaeotis','Dermanura phaeotis','Dermanura','Phyllostomidae','Bat','Frugivore','1','1.0',NULL,NULL,NULL,'source: IUCN Red List website'),(25,'sp.','Dermanura sp.','Dermanura','Phyllostomidae','Bat','Frugivore','None','nan',NULL,NULL,NULL,'None'),(26,'tolteca'